	String AUTO_RETALIATE_SECTION = "autoRetaliateSection";

	@ConfigSection(
		name = "<html><table cellspacing=0 cellpadding=0><tr><td>XP Drops Button</td></tr></table></html>",
		description = "",
		position = 1
	)
	String XP_DROPS_SECTION = "xpDropsSection";

	@ConfigSection(
		name = "<html><table cellspacing=0 cellpadding=0><tr><td>Bank Placeholders</td></tr></table></html>",
		description = "",
		position = 2
	)
	String ALWAYS_SET_PLACEHOLDERS_SECTION = "alwaysSetPlaceholdersSection";

	@ConfigSection(
		name = "<html><table cellspacing=0 cellpadding=0><tr><td>Report Button</td></tr></table></html>",
		description = "",
		position = 3
	)
	String REPORT_SECTION = "reportSection";

	@ConfigSection(
		name = "<html><table cellspacing=0 cellpadding=0><tr><td>Left Click Off</td></tr></table></html>",
		description = "",
		position = 4
	)
	String LEFT_CLICK_OFF_SECTION = "leftClickOffSection";

	@ConfigItem(
		keyName = "autoRetaliate",
		name = "Toggle",
		description = "Enable/Disable",
		section = AUTO_RETALIATE_SECTION,
		position = 0
	)
	default ClickMode autoRetaliate()
	{
		return ClickMode.NORMAL;
	}

	@ConfigItem(
		keyName = "xpDrops",
		name = "Hide/Show/Setup",
		description = "",
		section = XP_DROPS_SECTION,
		position = 0
	)
	default ClickMode xpDrops()
	{
		return ClickMode.NORMAL;
	}

	@ConfigItem(
		keyName = "alwaysSetPlaceholders",
		name = "Toggle",
		description = "Enable/Disable",
		section = ALWAYS_SET_PLACEHOLDERS_SECTION,
		position = 0
	)
	default ClickMode alwaysSetPlaceholders()
	{
		return ClickMode.NORMAL;
	}

	@ConfigItem(
		keyName = "report",
		name = "Abuse/Game Bug",
		description = "",
		section = REPORT_SECTION,
		position = 0
	)
	default ClickMode report()
	{
		return ClickMode.NORMAL;
	}

	@ConfigItem(
		keyName = "deprioritizeLeftClickOffEntries",
		name = "Deprioritize menu entry",
		description = "",
		section = LEFT_CLICK_OFF_SECTION,
		position = 0
	)
	default boolean deprioritizeLeftClickOffEntries()
	{
		return true;
	}
}

